-- 3. GUARDIAN 
CREATE TABLE Guardian (
    guardian_id VARCHAR(50) PRIMARY KEY,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    relationship VARCHAR(50),
    contact_primary VARCHAR(20),
    contact_secondary VARCHAR(20),
    email VARCHAR(100),
    address VARCHAR(200));
