-- 5. CLASS (depends on Academic_Year and Teacher)
CREATE TABLE Class (
    class_id VARCHAR(50) PRIMARY KEY,
    year_id VARCHAR(20) NOT NULL,
    grade_level VARCHAR(20) NOT NULL,
    section VARCHAR(10) NOT NULL,
    class_teacher_id VARCHAR(50),
    room_number VARCHAR(20),
    class_strength INT,
    CONSTRAINT FK_Class_AcademicYear FOREIGN KEY (year_id) REFERENCES Academic_Year(year_id),
    CONSTRAINT FK_Class_Teacher FOREIGN KEY (class_teacher_id) REFERENCES Teacher(teacher_id));
go
