-- 6. STUDENT (depends on Class and Guardian)
CREATE TABLE Student (
    student_id VARCHAR(50) PRIMARY KEY,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    gender VARCHAR(10),
    date_of_birth DATE,
    class_id VARCHAR(50),
    guardian_id VARCHAR(50),
    admission_date DATE,
    email VARCHAR(100),
    phone_no VARCHAR(20),
    CONSTRAINT FK_Student_Class FOREIGN KEY (class_id) REFERENCES Class(class_id),
    CONSTRAINT FK_Student_Guardian FOREIGN KEY (guardian_id) REFERENCES Guardian(guardian_id));
go
--1260 entries
go

-- 7. EVENT (organizer is a Teacher)
CREATE TABLE Event (
    event_id VARCHAR(50) PRIMARY KEY,
    event_name VARCHAR(100),
    description VARCHAR(255),
    event_date DATE,
    location VARCHAR(100),
    organizer_id VARCHAR(50),
    CONSTRAINT FK_Event_Organizer FOREIGN KEY (organizer_id) REFERENCES Teacher(teacher_id));
