-- 10. TimeTable (depends on Class, Subject)
CREATE TABLE TimeTable (
    timetable_id VARCHAR(50) PRIMARY KEY,
    class_id VARCHAR(50) NOT NULL,
    subject_id VARCHAR(50) NOT NULL,
    day_of_week VARCHAR(20),
    start_time TIME,
    end_time TIME,
    room_no VARCHAR(20),
    CONSTRAINT FK_TT_Class FOREIGN KEY (class_id) REFERENCES Class(class_id),
    CONSTRAINT FK_TT_Subject FOREIGN KEY (subject_id) REFERENCES Subject(subject_id));
go
go
-- 11. EXAM (depends on Class, Subject, Academic_Year)
CREATE TABLE Exam (
    exam_id VARCHAR(50) PRIMARY KEY,
    exam_name VARCHAR(100),
    year_id VARCHAR(20) NOT NULL,
    class_id VARCHAR(50) NOT NULL,
    subject_id VARCHAR(50) NOT NULL,
    exam_date DATE,
    total_marks INT,
    CONSTRAINT FK_Exam_Year FOREIGN KEY (year_id) REFERENCES Academic_Year(year_id),
    CONSTRAINT FK_Exam_Class FOREIGN KEY (class_id) REFERENCES Class(class_id),
    CONSTRAINT FK_Exam_Subject FOREIGN KEY (subject_id) REFERENCES Subject(subject_id));
go
go
-- 12. FEE (depends on Student and Academic_Year)
CREATE TABLE Fee (
    fee_id VARCHAR(50) PRIMARY KEY,
    student_id VARCHAR(50) NOT NULL,
    year_id VARCHAR(20) NOT NULL,
    title VARCHAR(100),
    amount_due DECIMAL(10,2),
    due_date DATE,
    status VARCHAR(20), -- Paid, Pending, Overdue
    CONSTRAINT FK_Fee_Student FOREIGN KEY (student_id) REFERENCES Student(student_id),
    CONSTRAINT FK_Fee_Year FOREIGN KEY (year_id) REFERENCES Academic_Year(year_id));
go
go
-- 13. PAYMENT (depends on Fee)
CREATE TABLE Payment (
    payment_id VARCHAR(50) PRIMARY KEY,
    fee_id VARCHAR(50) NOT NULL,
    amount_paid DECIMAL(10,2) NOT NULL,
    payment_date DATE NOT NULL,
    fine_amount DECIMAL(10,2) DEFAULT 0,
    CONSTRAINT FK_Payment_Fee FOREIGN KEY (fee_id) REFERENCES Fee(fee_id));
go

go
-- 14. EXAM_RESULT (depends on Student and Exam)
CREATE TABLE Exam_Result (
    result_id VARCHAR(50) PRIMARY KEY,
    student_id VARCHAR(50) NOT NULL,
    exam_id VARCHAR(50) NOT NULL,
    marks_obtained DECIMAL(7,2),
    grade VARCHAR(5),
    remarks VARCHAR(255),
    CONSTRAINT UQ_ExamResult_StudentExam UNIQUE (student_id, exam_id),
    CONSTRAINT FK_ExamResult_Student FOREIGN KEY (student_id) REFERENCES Student(student_id),
    CONSTRAINT FK_ExamResult_Exam FOREIGN KEY (exam_id) REFERENCES Exam(exam_id));
go

go
-- 15. ATTENDANCE (depends on Student)
CREATE TABLE Attendance (
    attendance_id VARCHAR(50) PRIMARY KEY,
    student_id VARCHAR(50) NOT NULL,
    date DATE NOT NULL,
    status VARCHAR(20) NOT NULL, -- Present, Absent, Late, Excused
    CONSTRAINT UQ_Attendance_StudentDate UNIQUE (student_id, date),
    CONSTRAINT FK_Attendance_Student FOREIGN KEY (student_id) REFERENCES Student(student_id));
go
go

--Queries
--1. Display student's info with overdue or pending fees
SELECT s.student_id,s.first_name + ' ' + s.last_name AS student_name,
f.title,f.amount_due,f.due_date,f.status
FROM Fee f
JOIN Student s ON f.student_id = s.student_id
WHERE f.status IN ('Unpaid', 'Partial');

--2. Display Total Fee Assigned to Each Student (Per Year)
SELECT s.student_id,s.first_name + ' ' + s.last_name AS student_name,f.year_id,
SUM(f.amount_due) AS total_yearly_fee
FROM Fee f
JOIN Student s ON f.student_id = s.student_id
GROUP BY s.student_id, s.first_name, s.last_name, f.year_id;

--3. Attendance Count for Each Student (e.g., Present Only)(we have 
SELECT s.student_id, s.first_name + ' ' + s.last_name AS student_name,
COUNT(a.attendance_id) AS present_days
FROM Student s
JOIN Attendance a ON s.student_id = a.student_id
WHERE a.status = 'Present'
GROUP BY s.student_id, s.first_name, s.last_name
ORDER BY present_days DESC;

--4. Subjects a Student Is Studying (Beautiful Join Chain)
SELECT s.student_id,s.first_name + ' ' + s.last_name AS student_name,sub.subject_name, c.grade_level,
c.section
FROM Student s
JOIN Class c ON s.class_id = c.class_id
JOIN Class_Subject_Mapping csm ON c.class_id = csm.class_id
JOIN Subject sub ON csm.subject_id = sub.subject_id
ORDER BY s.student_id, sub.subject_name;

--5 Students whose marks are above class average (Our topper Gang)
SELECT s.student_id,s.first_name,er.marks_obtained,
'Our topper gang' AS comment
FROM Exam_Result er
JOIN Student s ON er.student_id = s.student_id
WHERE er.marks_obtained > (SELECT AVG(marks_obtained)  
                            FROM Exam_Result WHERE exam_id = er.exam_id);

--6. Show announcements posted by a specific teacher (Explicit JOIN)
SELECT a.announcement_id, a.title, a.date_posted, t.first_name, t.last_name
FROM Announcement AS a
INNER JOIN Teacher AS t
ON a.posted_by = t.teacher_id
WHERE t.teacher_id = 'T-018' 
ORDER BY a.date_posted DESC;

--7. Siblings detected (same guardian_id)
SELECT g.guardian_id, STRING_AGG(s.first_name + ' ' + s.last_name, ', ') AS siblings
FROM Guardian g
JOIN Student s ON g.guardian_id = s.guardian_id
GROUP BY g.guardian_id
HAVING COUNT(s.student_id) > 1;

--8. Teachers with too many courses — “Overworked Heroes”
SELECT t.teacher_id, t.first_name + ' ' + t.last_name AS teacher_name,
COUNT(csm.subject_id) AS subjects_taught
FROM Teacher t
JOIN Class_Subject_Mapping csm 
ON t.teacher_id = csm.teacher_id
JOIN Subject s
ON csm.subject_id = s.subject_id
GROUP BY t.teacher_id, t.first_name, t.last_name
HAVING COUNT(csm.subject_id) > 3;

--9.Teachers who have no announcements (“Silent Teachers Club”)
SELECT t.teacher_id,t.first_name,t.last_name
FROM Teacher t
LEFT JOIN Announcement a 
ON t.teacher_id = a.posted_by
WHERE a.posted_by IS NULL;

--10.Teachers Teaching the Most Subjects
SELECT TOP 5 t.teacher_id,t.first_name + ' ' + t.last_name AS teacher_name,
COUNT(csm.subject_id) AS total_subjects
FROM Teacher t
JOIN Class_Subject_Mapping csm ON t.teacher_id = csm.teacher_id
GROUP BY t.teacher_id, t.first_name, t.last_name
ORDER BY total_subjects DESC;

--11. Average Marks Per Class for Each Subject
SELECT c.class_id,sub.subject_name,
AVG(er.marks_obtained) AS avg_marks
FROM Exam_Result er
JOIN Exam e ON er.exam_id = e.exam_id
JOIN Class c ON c.class_id = e.class_id
JOIN Subject sub ON sub.subject_id = e.subject_id
GROUP BY c.class_id, sub.subject_name
ORDER BY c.class_id, avg_marks DESC;

--12. Total Fee Assigned vs Paid Per Student
SELECT s.student_id,s.first_name + ' ' + s.last_name AS student_name,
SUM(f.amount_due) AS total_fee_assigned,
ISNULL(SUM(p.amount_paid), 0) AS total_paid
FROM Student s
JOIN Fee f ON s.student_id = f.student_id
LEFT JOIN Payment p ON f.fee_id = p.fee_id
GROUP BY s.student_id, s.first_name, s.last_name;


--13. Total Students Per Class With Class Teacher Name
SELECT c.class_id, c.grade_level, c.section,
t.first_name + ' ' + t.last_name AS class_teacher,
COUNT(s.student_id) AS total_students
FROM Class c
LEFT JOIN Teacher t ON c.class_teacher_id = t.teacher_id
LEFT JOIN Student s ON s.class_id = c.class_id
GROUP BY c.class_id, c.grade_level, c.section, t.first_name, t.last_name
ORDER BY total_students DESC;


--14. List All Subjects Taught by Each Teacher (Detailed)
SELECT t.teacher_id, t.first_name + ' ' + t.last_name AS teacher_name,
sub.subject_name,c.class_id
FROM Teacher t
JOIN Class_Subject_Mapping csm ON t.teacher_id = csm.teacher_id
JOIN Subject sub ON csm.subject_id = sub.subject_id
JOIN Class c ON c.class_id = csm.class_id
ORDER BY teacher_name, sub.subject_name;


--15. Total Fee Collected vs Remaining Per Academic Year
SELECT ay.year_id,SUM(f.amount_due) AS total_fee_assigned,
SUM(ISNULL(p.amount_paid, 0)) AS total_paid,
SUM(f.amount_due) - SUM(ISNULL(p.amount_paid, 0)) AS remaining
FROM Academic_Year ay
JOIN Fee f ON ay.year_id = f.year_id
LEFT JOIN Payment p ON f.fee_id = p.fee_id
GROUP BY ay.year_id
ORDER BY ay.year_id;

--16. Highest Marks Per Exam
SELECT e.exam_id, e.exam_name, sub.subject_name,
MAX(er.marks_obtained) AS highest_marks
FROM Exam_Result er
JOIN Exam e ON er.exam_id = e.exam_id
JOIN Subject sub ON e.subject_id = sub.subject_id
GROUP BY e.exam_id, e.exam_name, sub.subject_name
ORDER BY highest_marks DESC;

--17. Students Who Failed Any Subject (Assuming Passing Marks = 40)
SELECT s.student_id, s.first_name + ' ' + s.last_name AS student_name,
sub.subject_name, er.marks_obtained
FROM Exam_Result er
JOIN Exam e ON er.exam_id = e.exam_id
JOIN Subject sub ON e.subject_id = sub.subject_id
JOIN Student s ON er.student_id = s.student_id
WHERE er.marks_obtained < 40
ORDER BY s.student_id, sub.subject_name;

--18. Students whose names start with the same letter as their guardian
SELECT s.student_id, s.first_name AS student, g.first_name AS guardian
FROM Student s
JOIN Guardian g ON s.guardian_id = g.guardian_id
WHERE LEFT(s.first_name,1) = LEFT(g.first_name,1);

--19.Student's Percentage across all exams
SELECT s.student_id, s.first_name + ' ' + s.last_name AS student_name,
SUM(er.marks_obtained) AS total_marks_obtained,
SUM(e.total_marks) AS total_marks_possible,
(SUM(er.marks_obtained) * 100.0 / SUM(e.total_marks)) AS percentage
FROM Exam_Result er
JOIN Student s ON er.student_id = s.student_id
JOIN Exam e ON er.exam_id = e.exam_id
GROUP BY s.student_id, s.first_name, s.last_name
ORDER BY percentage DESC;

--20.Comprehensive Student Performance Dashboard
SELECT s.student_id,s.first_name + ' ' + s.last_name AS student_name,
c.grade_level + '-' + c.section AS class,
COUNT(a.attendance_id) AS total_attendance_days,
SUM(CASE WHEN a.status = 'Present' THEN 1 ELSE 0 END) AS days_present,
SUM(CASE WHEN a.status = 'Absent' THEN 1 ELSE 0 END) AS days_absent,
SUM(er.marks_obtained) AS total_marks_obtained,
SUM(e.total_marks) AS total_marks_possible,
(SUM(er.marks_obtained) * 100.0 / SUM(e.total_marks)) AS exam_percentage,
SUM(CASE WHEN f.status = 'Paid' THEN f.amount_due ELSE 0 END) AS fees_paid,
SUM(CASE WHEN f.status <> 'Paid' THEN f.amount_due ELSE 0 END) AS fees_pending
FROM Student s
JOIN Class c ON s.class_id = c.class_id
LEFT JOIN Attendance a ON s.student_id = a.student_id
LEFT JOIN Exam_Result er ON s.student_id = er.student_id
LEFT JOIN Exam e ON er.exam_id = e.exam_id
LEFT JOIN Fee f ON s.student_id = f.student_id
GROUP BY s.student_id, s.first_name, s.last_name, c.grade_level, c.section
ORDER BY exam_percentage DESC, days_present DESC;
