('SUB-001', 'English (Phonics)', 'Alphabet recognition and basic phonics (Oral & Written)'),
('SUB-002', 'Urdu (Haroof-e-Tahajji)', 'Recognition and writing of Urdu alphabets'),
('SUB-003', 'Mathematics (Early Years)', 'Number recognition, counting 1-100, and shapes'),
('SUB-004', 'General Knowledge (Oral)', 'Seasons, Body Parts, Animals, Colors (Oral only)'),
('SUB-005', 'Art & Activity', 'Coloring, cutting, pasting, and clay modeling'),
('SUB-006', 'Nazra Quran (Qaida)', 'Basic Noorani Qaida and small Masnoon Duas');
